  COLLECT_STALLED_TIMEOUT_MS: 30000,
  // The Stop collecting label (content.js, both pages) re-reads its count, passes and elapsed time once per tick while a run is active.
  COLLECT_STOP_LABEL_TICK_MS: 1000,
